style.css:
@-moz-document domain("youtube.com") {
:root{--accent:#ffd84d;--bg:url("https://raw.githubusercontent.com/newplayernewplayer280-bot/Rodamrix-theme/main/Rodamrix%20wallpaper.png");}
html::before{content:"";position:fixed;inset:0;background:linear-gradient(rgba(10,10,10,.72),rgba(10,10,10,.72)),var(--bg) center/cover fixed no-repeat;z-index:-99999}
html,body,ytd-app,#page-manager,#content,#columns,#primary,#secondary,#masthead-container,tp-yt-app-drawer,#guide-content{background:transparent!important}
#masthead-container,#guide-content,tp-yt-app-drawer,ytd-popup-container{background:rgba(22,22,22,.42)!important;backdrop-filter:blur(20px);border:1px solid rgba(255,216,77,.12);border-radius:16px}
ytd-rich-grid-renderer{max-width:none!important;--ytd-rich-grid-items-per-row:5!important;--ytd-rich-grid-posts-per-row:5!important}
#contents.ytd-rich-grid-renderer{max-width:none!important;width:100%!important}
ytd-rich-item-renderer,ytd-video-renderer{background:rgba(30,30,30,.28)!important;border:1px solid rgba(255,216,77,.08);border-radius:18px;backdrop-filter:blur(14px);transition:.2s}
ytd-rich-item-renderer:hover,ytd-video-renderer:hover{transform:translateY(-3px);box-shadow:0 0 18px rgba(255,216,77,.18);border-color:rgba(255,216,77,.35)}
ytd-thumbnail img{border-radius:16px!important}
#search{background:rgba(35,35,35,.45)!important;border-radius:999px!important}
::-webkit-scrollbar{width:10px}::-webkit-scrollbar-thumb{background:rgba(255,216,77,.4);border-radius:20px}
}
